METRO_DEFS = [
    {"metro": "Atlanta", "label": "Atlanta and Metro Atlanta", "basename": "Attorney-Referral-List-Atlanta",
     "match": {"area_codes": ["404","678","770","470","762"], "states": ["GA"],
               "cities": ["atlanta","marietta","alpharetta","roswell","sandy springs","decatur","smyrna","duluth","lawrenceville","johns creek","kennesaw","woodstock"],
               "zip_prefixes": ["300","301","302","303"]}, "firms": ATLANTA},
    {"metro": "Nashville", "label": "Nashville and Middle Tennessee", "basename": "Attorney-Referral-List-Nashville",
     "match": {"area_codes": ["615","629","931"], "states": ["TN"],
               "cities": ["nashville","franklin","brentwood","murfreesboro","hendersonville","mount juliet","gallatin","lebanon","smyrna"],
               "zip_prefixes": ["370","371","372"]}, "firms": NASHVILLE},
    {"metro": "Charlotte", "label": "Charlotte and Metro Charlotte", "basename": "Attorney-Referral-List-Charlotte",
     "match": {"area_codes": ["704","980"], "states": ["NC"],
               "cities": ["charlotte","concord","gastonia","huntersville","matthews","mooresville","cornelius","indian trail","pineville","mint hill"],
               "zip_prefixes": ["280","281","282"]}, "firms": CHARLOTTE},
]

for m in METRO_DEFS:
    n_e = sum(1 for f in m["firms"] if f["type"].startswith("Estate"))
    p = METROS / f"{m['metro'].lower()}.json"
    p.write_text(json.dumps(m, indent=2), encoding="utf-8")
    print(f"{m['metro']}: {len(m['firms'])} firms ({n_e} estate, {len(m['firms'])-n_e} divorce) -> {p.name}")
    r = subprocess.run(["py", "scripts/build-curated-list.py", str(p)], cwd=str(REPO), capture_output=True, text=True)
    print("  build:", (r.stdout or r.stderr).strip().splitlines()[-1] if (r.stdout or r.stderr).strip() else "(ok)")
print("\n--- running strict QC verifier on all lists ---")
subprocess.run(["py", "scripts/verify-curated-lists.py"], cwd=str(REPO))
